import { loadFont } from "@remotion/google-fonts/Inter";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// OMNIPRIME — terceira versão: o vídeo de referência do cliente como base, com a identidade da landing.
// Da referência vem a estrutura: espaço escuro com poeira, texto neon inclinado entrando em perspectiva, blocos
// empilhando com a câmera olhando de baixo, o iceberg ("o lado que você não vê"), a parede de telas, a virada
// "não é X / é Y" em fundo claro com ícones neon e risco vermelho, a plataforma branca com o logo e o bloco que sobe
// brilhando, e a legenda pequena em itálico o tempo todo.
// Da landing vem a identidade: azul-marinho #08335A / #061326 no lugar do roxo, dourado #F2B705 como brilho, Inter,
// o leão com a coroa, a assistente "Lia", os cartões brancos do CRM e o botão verde "Falar no WhatsApp".
// Locução "o locutor" (audio/omniprime2-vo.wav), entra em 0,15 s. Sem áudio aqui.

const { fontFamily: FONT } = loadFont("normal", { weights: ["500", "600", "700", "800"], subsets: ["latin", "latin-ext"] });

export const OP3_FPS = 30;
const VO = 0.15;
export const OP3_FRAMES = 30 * OP3_FPS;
const WHITE = "#FFFFFF";
const ICE = "#EEF3F9";
const CHAT = "#EAF1F9";
const LINE = "#DCE4EE";
const NAVY = "#08335A";
const INK = "#0B2038";
const MUTE = "#52627A";
const GOLD = "#F2B705";
const RED = "#FF5A5F";
const WA = "#1B9E52";
const MINT = "#2EE6A6";
const BLUE = "#5B7CFA";
const asset = (f: string) => staticFile(`omniprime/${f}`);

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const IN_OUT = Easing.bezier(0.65, 0, 0.35, 1);
const BACK = Easing.out(Easing.back(1.5));
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const io = (t: number, a: number, d = 0.5) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: IN_OUT });
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const mix = (a: number, b: number, p: number) => a + (b - a) * p;
const v = (s: number) => s + VO;
const bump = (t: number, at: number, amt = 0.06, d = 0.4) => (t >= at ? amt * (1 - k(t, at, d)) : 0);
const slab = (c: string, n = 12) => Array.from({ length: n }, (_, i) => `0 ${i + 1}px 0 ${c}`).join(", ");
const glow = (c: string, s = 1) => `0 0 ${6 * s}px ${c}, 0 0 ${22 * s}px ${c}, 0 0 ${54 * s}px ${c}`;

// ───────── o espaço: azul-marinho profundo com poeira passando (claro na cena da virada) ─────────
const DUST = Array.from({ length: 96 }, (_, i) => ({ x: (i * 197.31) % 1180, y: (i * 331.77) % 2020, d: 0.3 + ((i * 37) % 10) / 10, s: 2 + ((i * 53) % 5), streak: i % 6 === 0 }));
const Space: React.FC<{ t: number; light: number }> = ({ t, light }) => (
  <AbsoluteFill style={{ background: "radial-gradient(120% 75% at 50% 42%, #0E3566 0%, #071D3B 42%, #030A14 100%)", overflow: "hidden" }}>
    {light > 0 ? <AbsoluteFill style={{ opacity: light, background: "radial-gradient(110% 70% at 50% 45%, #FFFFFF 0%, #EEF3F9 52%, #BCC8D9 100%)" }} /> : null}
    {DUST.map((p, i) => {
      const x = ((((p.x - t * 30 * p.d) % 1180) + 1180) % 1180) - 50;
      const y = ((((p.y - t * 58 * p.d) % 2020) + 2020) % 2020) - 50;
      return <div key={i} style={{ position: "absolute", left: x, top: y, width: p.s, height: p.streak ? p.s * 9 : p.s, borderRadius: p.s, background: light > 0.5 ? NAVY : i % 9 === 0 ? GOLD : WHITE, opacity: (light > 0.5 ? 0.16 : 0.22) + p.d * (p.streak ? 0.15 : 0.45), transform: `rotate(${p.streak ? 27 : 0}deg)`, filter: p.d > 1 ? "blur(1.5px)" : undefined }} />;
    })}
  </AbsoluteFill>
);
const Stage: React.FC<{ children: React.ReactNode; origin?: string; depth?: number }> = ({ children, origin = "50% 50%", depth = 1400 }) => (
  <AbsoluteFill style={{ perspective: depth, perspectiveOrigin: origin }}>{children}</AbsoluteFill>
);

// ───────── texto neon, palavra por palavra ─────────
type W = [string, number, string?];
const NLine: React.FC<{ t: number; words: W[]; size: number; weight?: number; color?: string; g?: string; gs?: number; italic?: boolean }> = ({ t, words, size, weight = 800, color = WHITE, g = GOLD, gs = 1, italic = true }) => (
  <div style={{ display: "flex", justifyContent: "center", alignItems: "baseline", gap: size * 0.27, whiteSpace: "nowrap", fontFamily: FONT, fontWeight: weight, fontSize: size, lineHeight: 1.1, letterSpacing: "-0.03em", color, transform: italic ? "skewX(-8deg)" : undefined }}>
    {words.map(([w, at, c], i) => {
      const e = k(t, v(at) - 0.05, 0.3);
      return (
        <span key={i} style={{ display: "inline-block", opacity: k(t, v(at) - 0.05, 0.1), transform: `translateY(${((1 - e) * size * 0.4).toFixed(1)}px) scale(${(0.6 + 0.4 * pop(t, v(at) - 0.05, 0.4)).toFixed(3)})`, textShadow: glow(c ?? g, gs) }}>{w}</span>
      );
    })}
  </div>
);

// ───────── legenda pequena em itálico, como na referência ─────────
const SUBS: [string, number][] = [
  ["Sua empresa ainda", 0.17], ["perde venda", 0.81], ["porque um cliente", 1.45], ["ficou sem retorno?", 2.09], ["", 3.05],
  ["Uma proposta", 3.24], ["esquecida,", 3.76], ["", 4.45], ["um interessado", 4.62], ["que ninguém", 5.32], ["acompanhou.", 5.8], ["", 6.42],
  ["É pra isso", 6.58], ["que existe", 7.06], ["", 7.65], ["o OMNIPRIME,", 7.9], ["", 8.75], ["o CRM", 8.9], ["da Viaprime.", 9.95], ["", 10.85],
  ["Ele automatiza", 11.25], ["o acompanhamento,", 12.03], ["coloca agentes", 12.99], ["de inteligência artificial", 13.75], ["no atendimento,", 14.91], ["", 15.75],
  ["faz pesquisa", 15.91], ["de satisfação", 16.54], ["", 17.5], ["e reativa", 17.66], ["sua base", 18.34], ["com campanhas.", 19.08], ["", 19.95],
  ["Talvez você", 20.26], ["não perca vendas", 20.72], ["por falta de clientes,", 21.64], ["", 22.8], ["e sim", 22.95], ["por falta", 23.55], ["de acompanhamento.", 24.05], ["", 25.15],
  ["OMNIPRIME", 25.47], ["não deixa", 26.35], ["oportunidades", 26.81], ["pra trás.", 27.61], ["", 28.45],
];
const Subs: React.FC<{ t: number; dark: boolean }> = ({ t, dark }) => {
  let cur: [string, number] | null = null;
  for (const s of SUBS) if (t >= v(s[1]) - 0.06) cur = s;
  if (!cur || !cur[0]) return null;
  const e = k(t, v(cur[1]) - 0.06, 0.16);
  return (
    <div style={{ position: "absolute", left: 0, right: 0, top: 1432, textAlign: "center", fontFamily: FONT, fontWeight: 500, fontSize: 46, letterSpacing: "-0.01em", color: dark ? WHITE : INK, textShadow: dark ? "0 2px 14px rgba(0,0,0,0.9), 0 0 4px rgba(0,0,0,0.7)" : "0 0 14px rgba(255,255,255,0.9)", opacity: e, transform: `translateY(${(1 - e) * 10}px) skewX(-9deg)`, zIndex: 20 }}>{cur[0]}</div>
  );
};

// ───────── peças ─────────
const Person: React.FC<{ s: number; c: string; bg: string; style?: React.CSSProperties }> = ({ s, c, bg, style }) => (
  <div style={{ width: s, height: s, borderRadius: s / 2, background: bg, display: "flex", alignItems: "flex-end", justifyContent: "center", overflow: "hidden", flexShrink: 0, boxSizing: "border-box", ...style }}>
    <div style={{ width: s * 0.6, height: s * 0.38, borderRadius: `${s * 0.32}px ${s * 0.32}px 0 0`, background: c, position: "relative" }}>
      <div style={{ position: "absolute", left: s * 0.12, top: -s * 0.38, width: s * 0.36, height: s * 0.36, borderRadius: s * 0.18, background: c }} />
    </div>
  </div>
);
const Bubble: React.FC<{ text: string; e: number; mine?: boolean; size?: number }> = ({ text, e, mine, size = 34 }) => (
  <div style={{ alignSelf: mine ? "flex-end" : "flex-start", maxWidth: "86%", background: mine ? NAVY : WHITE, color: mine ? WHITE : INK, borderRadius: 28, borderBottomLeftRadius: mine ? 28 : 8, borderBottomRightRadius: mine ? 8 : 28, padding: "18px 24px", fontFamily: FONT, fontWeight: 600, fontSize: size, lineHeight: 1.22, opacity: Math.min(1, e * 3), transform: `translateY(${(1 - e) * 40}px) scale(${0.85 + 0.15 * e})`, transformOrigin: mine ? "100% 100%" : "0 100%", boxShadow: "0 8px 20px rgba(8,51,90,0.10)" }}>{text}</div>
);
// o bloco do logo: azul-marinho, borda e brilho dourados, o leão com a coroa
const EmblemTile: React.FC<{ s: number; lit?: number }> = ({ s, lit = 1 }) => (
  <div style={{ width: s, height: s, borderRadius: s * 0.22, background: "linear-gradient(155deg, #134A86 0%, #08335A 55%, #05203B 100%)", border: `${Math.max(4, s * 0.02)}px solid ${GOLD}`, boxSizing: "border-box", boxShadow: `${slab("#B88B00", Math.round(s * 0.05))}, 0 0 ${40 * lit}px ${GOLD}, 0 0 ${130 * lit}px rgba(242,183,5,${0.7 * lit}), inset 0 0 50px rgba(242,183,5,0.25)`, display: "flex", alignItems: "center", justifyContent: "center" }}>
    <Img src={asset("viaprime-emblema.png")} style={{ width: s * 0.66 }} />
  </div>
);

// ───────── cena 1: o texto neon entra inclinado; as mensagens sem resposta empilham e a câmera olha de baixo ─────────
const NOTES: [string, string, string, number][] = [
  ["Oi! Ainda tem disponível?", "há 3 dias", GOLD, 1.45],
  ["Consegue passar o valor?", "há 2 dias", BLUE, 1.85],
  ["Alô? Tem alguém aí?", "ontem", RED, 2.24],
];
const Lost: React.FC<{ t: number }> = ({ t }) => {
  const sweep = k(t, -0.22, 0.95);
  const leave = io(t, 1.22, 0.45);
  const up = io(t, 1.45, 1.35);
  const hit = v(2.52) - 0.05;
  const shake = t > hit && t < hit + 0.4 ? 8 : 0;
  const sq = io(t, 0.95, 0.55);
  return (
    <>
      {t < 1.75 ? (
        <Stage depth={1000}>
          <div style={{ position: "absolute", left: 0, right: 0, top: 660, display: "flex", flexDirection: "column", alignItems: "center", gap: 6, transform: `translate3d(${(mix(-300, 0, sweep) - leave * 1000).toFixed(1)}px, ${mix(160, 0, sweep).toFixed(1)}px, ${(mix(-700, 0, sweep) + lin(t, 0, 1.3) * 90 + leave * 260).toFixed(1)}px) rotateY(${(mix(62, -8, sweep) - leave * 60).toFixed(2)}deg) rotateZ(${mix(16, -3, sweep).toFixed(2)}deg)`, opacity: 1 - leave }}>
            <NLine t={t} size={96} weight={500} g="rgba(255,255,255,0.55)" gs={0.6} words={[["Sua", -0.6], ["empresa", -0.45], ["ainda", 0.5]]} />
            <NLine t={t} size={134} g={RED} words={[["PERDE", 0.81], ["VENDA", 1.13]]} />
          </div>
        </Stage>
      ) : null}
      {/* clarão de abertura */}
      {t < 0.7 ? <div style={{ position: "absolute", left: 540 - 500, top: 800 - 500, width: 1000, height: 1000, borderRadius: 500, background: `radial-gradient(circle, rgba(255,90,95,0.55) 0%, rgba(255,90,95,0) 65%)`, transform: `scale(${(0.5 + k(t, 0, 0.7) * 1.4).toFixed(3)})`, opacity: 1 - k(t, 0, 0.7) }} /> : null}
      {/* o risco que leva o olho até a primeira mensagem */}
      <svg width={1080} height={400} viewBox="0 0 1080 400" style={{ position: "absolute", left: 0, top: 760, opacity: 1 - lin(t, 1.7, 2.0), filter: `drop-shadow(0 0 14px ${GOLD})` }}>
        <path d="M -20 250 C 120 120, 200 340, 320 220 S 470 150, 560 200" fill="none" stroke={GOLD} strokeWidth={9} strokeLinecap="round" pathLength={1} strokeDasharray="1" strokeDashoffset={1 - sq} />
      </svg>
      <Stage depth={1150} origin="50% 58%">
        <div style={{ position: "absolute", inset: 0, transformStyle: "preserve-3d", transform: `translate3d(${(Math.sin(t * 67) * shake).toFixed(1)}px, ${(mix(-250, 20, up) + Math.cos(t * 59) * shake).toFixed(1)}px, ${(up * -160 + lin(t, 1.4, 3.31) * 110).toFixed(1)}px) rotateX(${(up * 27).toFixed(2)}deg) rotateY(${(mix(30, -15, io(t, 1.35, 1.7)) + Math.sin(t * 1.4) * 2).toFixed(2)}deg)` }}>
          {NOTES.map(([msg, when, c, at], i) => {
            if (t < at) return null;
            const e = pop(t, at, 0.5);
            return (
              <div key={i} style={{ position: "absolute", left: 200 + (i % 2 ? 36 : -30), top: 1160 - i * 300, width: 680, height: 236, borderRadius: 50, background: "linear-gradient(160deg, #164680 0%, #0A2547 100%)", border: `4px solid ${c}`, boxShadow: `${slab("#041326", 16)}, 0 0 34px ${c}, 0 0 110px ${c}, inset 0 0 44px rgba(255,255,255,0.08)`, transform: `translateZ(${i * 80 + (1 - e) * -500}px) scale(${e.toFixed(3)}) rotateZ(${((1 - e) * -14 + (i % 2 ? 2 : -2)).toFixed(2)}deg)`, opacity: Math.min(1, e * 3), display: "flex", alignItems: "center", gap: 26, padding: "0 34px", boxSizing: "border-box" }}>
                <Person s={116} c="#0A2547" bg={c} />
                <div>
                  <div style={{ fontFamily: FONT, fontWeight: 800, fontSize: 30, color: "#B9CCE6", letterSpacing: "0.02em" }}>CLIENTE</div>
                  <div style={{ fontFamily: FONT, fontWeight: 700, fontSize: 34, color: WHITE, whiteSpace: "nowrap", letterSpacing: "-0.02em" }}>{msg}</div>
                  <div style={{ fontFamily: FONT, fontWeight: 700, fontSize: 27, color: "#FF9A9D", marginTop: 4 }}>{when} · sem resposta</div>
                </div>
              </div>
            );
          })}
          {/* anel em volta da primeira mensagem */}
          {t > 1.45 && t < 2.2 ? <div style={{ position: "absolute", left: 540 - 250, top: 1278 - 250, width: 500, height: 500, borderRadius: 250, border: `6px solid ${GOLD}`, boxShadow: glow(GOLD, 0.8), boxSizing: "border-box", transform: `scale(${(0.5 + k(t, 1.45, 0.7) * 1.3).toFixed(3)})`, opacity: 1 - k(t, 1.45, 0.7) }} /> : null}
        </div>
      </Stage>
      <div style={{ position: "absolute", left: 0, right: 0, top: 250, display: "flex", justifyContent: "center", opacity: k(t, hit, 0.08), transform: `scale(${(1 + (1 - k(t, hit, 0.32)) * 1.5).toFixed(3)}) rotate(-6deg)` }}>
        <div style={{ fontFamily: FONT, fontWeight: 800, fontSize: 118, color: WHITE, textShadow: glow(RED, 1.2), letterSpacing: "-0.03em", transform: "skewX(-8deg)", whiteSpace: "nowrap" }}>SEM RETORNO</div>
      </div>
    </>
  );
};

// ───────── cena 2: o iceberg — em cima as vendas que você vê; embaixo, a proposta esquecida e o interessado sem acompanhamento ─────────
const TIP: [number, number][] = [[250, 700], [300, 600], [360, 560], [400, 450], [450, 420], [500, 300], [540, 250], [585, 330], [630, 360], [680, 470], [740, 500], [790, 610], [850, 700]];
const UNDER: [number, number][] = [[850, 700], [930, 820], [990, 1000], [1000, 1220], [950, 1450], [900, 1650], [820, 1900], [730, 2120], [650, 2300], [570, 2460], [500, 2330], [400, 2130], [300, 1900], [200, 1650], [130, 1420], [80, 1200], [100, 980], [170, 820], [250, 700]];
const facets = (pts: [number, number][], ridge: [number, number][]) =>
  pts.slice(0, -1).map((p, i) => {
    const q = pts[i + 1];
    const my = (p[1] + q[1]) / 2;
    const r = ridge.reduce((a, b) => (Math.abs(b[1] - my) < Math.abs(a[1] - my) ? b : a));
    return { d: `M${p[0]} ${p[1]} L${q[0]} ${q[1]} L${r[0]} ${r[1]} Z`, a: ((i * 47) % 10) / 10 };
  });
const TIP_F = facets(TIP, [[540, 250], [548, 450], [552, 640]]);
const UNDER_F = facets(UNDER, [[560, 760], [520, 1000], [590, 1300], [530, 1650], [570, 2000], [570, 2300]]);
const poly = (p: [number, number][]) => p.map((q) => q.join(",")).join(" ");
const Iceberg: React.FC<{ t: number }> = ({ t }) => {
  const a = 3.31;
  const p1 = io(t, a + 0.02, 0.55);
  const p2 = io(t, v(4.62) - 0.32, 0.75);
  const cy = mix(mix(540, 1150, p1), 1760, p2) + lin(t, 5.2, 6.62) * 70;
  const s = mix(mix(1.55, 1.0, p1), 1.1, p2) + lin(t, 5.2, 6.62) * 0.05;
  const wave = (ph: number) => `M -1500 700 ${Array.from({ length: 31 }, (_, i) => `L ${-1500 + i * 140} ${(700 + Math.sin(i * 1.3 + t * 2.4 + ph) * 7).toFixed(1)}`).join(" ")}`;
  return (
    <div style={{ position: "absolute", left: 0, top: 0, width: 1080, height: 2700, transformOrigin: "0 0", transform: `translate(540px, 960px) scale(${s.toFixed(4)}) translate(-540px, ${(-cy).toFixed(1)}px) rotate(${(Math.sin(t * 0.9) * 0.8).toFixed(2)}deg)` }}>
      <svg width={1080} height={2700} viewBox="0 0 1080 2700" style={{ position: "absolute", left: 0, top: 0, overflow: "visible" }}>
        <defs>
          <linearGradient id="op3water" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stopColor="#2A7FD6" stopOpacity="0.5" />
            <stop offset="0.35" stopColor="#0E3F86" stopOpacity="0.55" />
            <stop offset="1" stopColor="#030A14" stopOpacity="0.9" />
          </linearGradient>
          <linearGradient id="op3tip" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stopColor="#FFFFFF" />
            <stop offset="1" stopColor="#B7D4F5" />
          </linearGradient>
          <linearGradient id="op3under" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stopColor="#8EC1FF" stopOpacity="0.62" />
            <stop offset="0.5" stopColor="#3C7FD9" stopOpacity="0.46" />
            <stop offset="1" stopColor="#123A7A" stopOpacity="0.4" />
          </linearGradient>
        </defs>
        <rect x={-1500} y={700} width={4080} height={2600} fill="url(#op3water)" />
        <g style={{ filter: "drop-shadow(0 0 30px rgba(120,180,255,0.55))" }}>
          <polygon points={poly(UNDER)} fill="url(#op3under)" stroke="rgba(190,225,255,0.5)" strokeWidth={3} />
          {UNDER_F.map((f, i) => (
            <path key={i} d={f.d} fill={f.a > 0.5 ? `rgba(255,255,255,${((f.a - 0.5) * 0.3).toFixed(3)})` : `rgba(3,14,34,${((0.5 - f.a) * 0.5).toFixed(3)})`} stroke="rgba(190,225,255,0.16)" strokeWidth={2} />
          ))}
        </g>
        <g style={{ filter: "drop-shadow(0 0 34px rgba(150,200,255,0.9))" }}>
          <polygon points={poly(TIP)} fill="url(#op3tip)" />
          {TIP_F.map((f, i) => (
            <path key={i} d={f.d} fill={f.a > 0.5 ? `rgba(255,255,255,${((f.a - 0.5) * 0.8).toFixed(3)})` : `rgba(8,51,90,${((0.5 - f.a) * 0.42).toFixed(3)})`} />
          ))}
        </g>
        <path d={wave(0)} fill="none" stroke="#CFE6FF" strokeWidth={5} style={{ filter: "drop-shadow(0 0 10px #8EC1FF)" }} />
        <path d={wave(2)} fill="none" stroke="rgba(207,230,255,0.4)" strokeWidth={3} transform="translate(0 16)" />
      </svg>
      {/* em cima: o que aparece */}
      <div style={{ position: "absolute", left: 0, right: 0, top: 96, textAlign: "center", fontFamily: FONT, fontWeight: 500, fontSize: 42, color: WHITE, textShadow: glow("rgba(255,255,255,0.5)", 0.5), transform: "skewX(-8deg)", opacity: k(t, a + 0.1, 0.3) }}>o que você vê</div>
      <div style={{ position: "absolute", left: 0, right: 0, top: 146, textAlign: "center", fontFamily: FONT, fontWeight: 800, fontSize: 62, color: WHITE, textShadow: glow(MINT, 0.8), transform: "skewX(-8deg)", letterSpacing: "-0.02em", opacity: k(t, a + 0.15, 0.3) }}>VENDAS FECHADAS</div>
      {[[400, MINT, WA], [545, GOLD, "#C99400"], [690, BLUE, "#3D5BD9"]].map(([x, g, bg], i) => {
        const e = pop(t, a + 0.1 + i * 0.1, 0.45);
        return (
          <div key={i} style={{ position: "absolute", left: (x as number) - 62, top: 520 + (i === 1 ? -70 : 0), width: 124, height: 124, borderRadius: 30, background: bg as string, boxShadow: `0 0 26px ${g}, 0 0 70px ${g}, ${slab("rgba(0,0,0,0.35)", 6)}`, display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${e.toFixed(3)}) translateY(${(Math.sin(t * 2.2 + i) * 6).toFixed(1)}px) rotate(${[-7, 3, 8][i]}deg)` }}>
            <svg width={72} height={72} viewBox="0 0 24 24" fill="none" stroke={WHITE} strokeWidth={3.4} strokeLinecap="round" strokeLinejoin="round">
              <path d="M5 12.5l4.500 4.500L19 7.500" />
            </svg>
          </div>
        );
      })}
      {/* embaixo: o que ninguém vê */}
      <div style={{ position: "absolute", left: 0, right: 0, top: 868, textAlign: "center", fontFamily: FONT, fontWeight: 500, fontSize: 44, color: "#D6E8FF", transform: "skewX(-8deg)", opacity: k(t, v(3.24) - 0.05, 0.3) * (1 - p2 * 0.6) }}>o que você não vê</div>
      <div style={{ position: "absolute", left: 0, right: 0, top: 930, display: "flex", flexDirection: "column", alignItems: "center", opacity: 1 - p2 * 0.55 }}>
        <NLine t={t} size={118} g={RED} color="#FFE7E3" words={[["PROPOSTA", 3.36]]} />
