// ───────── montagem: cada cena entra vindo do fundo e sai atravessando a câmera; a poeira nunca para ─────────
const SCENES: { C: React.FC<{ t: number }>; at: number }[] = [
  { C: Lost, at: 0 },
  { C: Iceberg, at: 3.31 },
  { C: Platform, at: 6.62 },
  { C: Wall, at: 11.29 },
  { C: Turn, at: 20.28 },
  { C: Sign, at: 25.42 },
];
export const OmniPrime3: React.FC = () => {
  const f = useCurrentFrame();
  const t = f / OP3_FPS;
  const light = lin(t, 20.12, 20.38) * (1 - lin(t, 25.26, 25.5));
  return (
    <AbsoluteFill style={{ background: "#030A14", fontFamily: FONT }}>
      <Space t={t} light={light} />
      {SCENES.map((s, i) => {
        const next = i + 1 < SCENES.length ? SCENES[i + 1].at : 1e9;
        if (t < s.at || t >= next) return null;
        const pin = i === 0 ? 1 : k(t, s.at, 0.4);
        const pout = interpolate(t, [next - 0.2, next], [0, 1], { ...cl, easing: Easing.in(Easing.cubic) });
        return (
          <AbsoluteFill key={i} style={{ overflow: "hidden", opacity: Math.min(1, pin * 2.5) * (1 - pout), transform: `scale(${((0.82 + 0.18 * pin) * (1 + pout * 0.7)).toFixed(4)})` }}>
            <s.C t={t} />
          </AbsoluteFill>
        );
      })}
      <Subs t={t} dark={light < 0.5} />
      <AbsoluteFill style={{ background: "radial-gradient(90% 70% at 50% 50%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.42) 100%)", opacity: 1 - light * 0.7, pointerEvents: "none" }} />
    </AbsoluteFill>
  );
};

